package scalaui.ui

/** A vector icon on a 24x24 grid, drawn as 1.75px round-capped strokes in one color (tinted at paint time). Rasterized crisply per display scale and cached.
  * Author your own with [[Icon.apply]] (SVG shapes inside a 24x24 viewBox; stroke attributes are inherited from the wrapper). */
final class Icon private (val name: String, val body: String, val strokeWidth: Double):
  lazy val doc: scalaui.svg.SvgDocument = scalaui.svg.SvgDocument.parse(
    s"""<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="#ffffff" stroke-width="$strokeWidth" stroke-linecap="round" stroke-linejoin="round">$body</svg>""")
  def thick(width: Double): Icon = new Icon(name, body, width)
  override def toString = s"Icon($name)"

object Icon:
  def apply(name: String, svgBody: String): Icon = new Icon(name, svgBody, 1.75)

